# Supported ADC pins: 32, 33, 34, 35, 36, 39

def get_pin(pin_num, mode=Pin.OUT):
    if pin_num not in pin_cache:
        pin_cache[pin_num] = Pin(pin_num, mode)
    return pin_cache[pin_num]

def set_pin(pin: int, state: int) -> dict:
    '''Sets a GPIO pin HIGH (1) or LOW (0).'''
