                    if r:
                        chunk = s.recv(1024).decode("utf-8")
                        if not chunk:
                            print("[Edge Brain] Connection closed by server.")
                            break
                        recv_buffer += chunk
                        while "\n" in recv_buffer:
                            line, recv_buffer = recv_buffer.split("\n", 1)
